const raw = $input.item.json || {};
const extracted = raw.extracted_params || {};

const project_id = raw.project_id || extracted.project_id || null;
const project_name = raw.project_name || 'Active Anime Project';
const episode_no = Number(raw.episode_no || raw.episode_number || extracted.episode_number || 1);
const season_no = Number(raw.season_no || raw.season_number || raw.current_season || extracted.season_no || 1);

const rawIntent = (raw.intent || raw.downstream_command || 'CHECK_CANON').toString().toUpperCase().trim();
const operation_mode = (rawIntent === 'UPDATE_CANON' || rawIntent === 'APPROVE_CANON_CHANGE') ? 'UPDATE_CANON' : 'CHECK_CANON';

const proposed_events = Array.isArray(raw.proposed_events) ? raw.proposed_events : (raw.user_prompt || raw.userPrompt || raw.rawText ? [{ event_code: `EVT_EP_${episode_no}`, description: (raw.user_prompt || raw.userPrompt || raw.rawText).toString() }] : []);
const characters_involved = Array.isArray(raw.characters_involved) && raw.characters_involved.length > 0 ? raw.characters_involved.map(c => c.toString().toUpperCase().trim()) : ['CHAR_001'];

const explicit_fact_updates = Array.isArray(raw.new_facts_to_add) ? raw.new_facts_to_add : [];
const explicit_knowledge_updates = Array.isArray(raw.new_knowledge_to_add) ? raw.new_knowledge_to_add : [];

if (!project_id) {
  throw new Error('WF-09 Error: project_id is strictly required (Rule 5 Project Isolation).');
}

return {
  json: {
    ...raw, project_id, project_name, episode_no, episode_number: episode_no, season_no, season_number: season_no,
    intent: rawIntent, operation_mode, proposed_events, characters_involved, explicit_fact_updates, explicit_knowledge_updates,
    sessionId: (raw.sessionId || `sess_${$execution.id}`).toString()
  }
};

const base = $('Input Normalizer & Mode Resolver').item.json;

function unpackRows(nodeName, requiredField) {
  try {
    const rawItems = $(nodeName).all().map(i => i.json);
    const rows = [];
    for (const entry of rawItems) {
      if (Array.isArray(entry)) { for (const r of entry) { if (r && r[requiredField] !== undefined) rows.push(r); } }
      else if (entry && entry[requiredField] !== undefined) { rows.push(entry); }
    }
    return rows;
  } catch (e) { return []; }
}

const canonFacts = unpackRows('Supabase: Fetch Canon Facts', 'fact_key');
const allKnowledge = unpackRows('Supabase: Fetch Character Knowledge', 'character_code');

const involvedSet = new Set(base.characters_involved || []);
const relevantKnowledge = allKnowledge.filter(k => involvedSet.size === 0 || involvedSet.has((k.character_code || '').toUpperCase().trim()) || k.secret === true);

const lockedFactsMap = {};
for (const cf of canonFacts) {
  const code = (cf.fact_key || '').toString().toUpperCase().trim();
  const isLocked = (cf.canon_status || '').toString().toUpperCase() === 'LOCKED';
  if (code && isLocked) {
    lockedFactsMap[code] = cf.fact_value;
  }
}

const deterministicViolations = [];
for (const candidate of (base.explicit_fact_updates || [])) {
  const code = (candidate.fact_key || '').toString().toUpperCase().trim();
  const newVal = typeof candidate.fact_value === 'object' ? JSON.stringify(candidate.fact_value) : String(candidate.fact_value);
  const oldVal = typeof lockedFactsMap[code] === 'object' ? JSON.stringify(lockedFactsMap[code]) : String(lockedFactsMap[code]);
  if (code && lockedFactsMap[code] !== undefined && newVal !== oldVal) {
    deterministicViolations.push({
      type: 'CRITICAL_CANON_VIOLATION',
      description: `Rule 14 & 15 Violation: Attempted to overwrite LOCKED canon fact '${code}' ("${oldVal}") with "${newVal}". Locked facts are immutable.`
    });
  }
}

const llmEvaluationContext = [
  `=== PROJECT: ${base.project_name} | EPISODE: ${base.episode_no} | MODE: ${base.operation_mode} ===`,
  `=== 1. EXISTING CANON FACTS (Rule 14 & 15: LOCKED facts cannot be contradicted) ===`,
  canonFacts.length > 0 ? canonFacts.map(f => `- [${f.canon_status}] ${f.fact_key} (${f.fact_type || 'LORE'}): ${JSON.stringify(f.fact_value)}`).join('\n') : 'No existing canon_facts rows yet.',
  `=== 2. CHARACTER KNOWLEDGE GRAPH (Section 42: Characters can ONLY act on facts they possess here) ===`,
  relevantKnowledge.length > 0 ? relevantKnowledge.map(k => `- Character ${k.character_code} KNOWS [${k.knowledge_key}] (Learned Ep ${k.learned_at_ep ?? 0}, Secret=${Boolean(k.secret)}): ${k.knowledge_value}`).join('\n') : 'No specialized character_knowledge rows recorded yet.',
  `=== 3. CHARACTERS INVOLVED IN CURRENT SCENE/EVENT ===`,
  JSON.stringify(base.characters_involved),
  `=== 4. PROPOSED EVENTS / SCRIPT ACTIONS TO VALIDATE ===`,
  JSON.stringify(base.proposed_events)
].join('\n\n');

return { json: { ...base, existing_canon_facts: canonFacts, existing_character_knowledge: allKnowledge, locked_facts_map: lockedFactsMap, deterministic_violations: deterministicViolations, llm_evaluation_context: llmEvaluationContext } };

const ctx = $('Deterministic Lock Guard & Prompt Builder').item.json;
const llmRaw = $input.item.json || {};
const lockedMap = ctx.locked_facts_map || {};

let parsed = null;
try {
  const content = llmRaw?.choices?.[0]?.message?.content;
  if (content) { parsed = JSON.parse(content.replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim()); }
} catch (e) { parsed = null; }

const llmViolations = Array.isArray(parsed?.violations) ? parsed.violations : [];
const combinedViolations = [...(ctx.deterministic_violations || []), ...llmViolations];

const rawNewFacts = [...(Array.isArray(ctx.explicit_fact_updates) ? ctx.explicit_fact_updates : []), ...(Array.isArray(parsed?.new_facts_to_add) ? parsed.new_facts_to_add : [])];
const rawNewKnowledge = [...(Array.isArray(ctx.explicit_knowledge_updates) ? ctx.explicit_knowledge_updates : []), ...(Array.isArray(parsed?.new_knowledge_to_add) ? parsed.new_knowledge_to_add : [])];

const safeFactsToUpsert = [];
for (let i = 0; i < rawNewFacts.length; i++) {
  const f = rawNewFacts[i] || {};
  const code = (f.fact_key || `FACT_EP${ctx.episode_no}_${i + 1}`).toString().toUpperCase().trim();
  const newVal = f.fact_value !== undefined ? f.fact_value : f.fact_statement;
  if (!newVal) continue;

  const newValStr = typeof newVal === 'object' ? JSON.stringify(newVal) : String(newVal);
  const oldValStr = typeof lockedMap[code] === 'object' ? JSON.stringify(lockedMap[code]) : String(lockedMap[code]);

  if (lockedMap[code] !== undefined && newValStr !== oldValStr) {
    combinedViolations.push({ type: 'CRITICAL_CANON_VIOLATION', description: `Hard Lock Protection (Rule 14/15): Mutation rejected for LOCKED fact '${code}'. Existing locked truth: "${oldValStr}".` });
    continue;
  }

  safeFactsToUpsert.push({
    project_id: ctx.project_id, fact_key: code, fact_type: (f.fact_type || 'LORE').toString(),
    fact_value: newVal, canon_status: (f.canon_status || 'FLEXIBLE').toString().toUpperCase(),
    affected_episodes: Array.isArray(f.affected_episodes) ? f.affected_episodes : [ctx.episode_no]
  });
}

const safeKnowledgeToUpsert = [];
for (let i = 0; i < rawNewKnowledge.length; i++) {
  const k = rawNewKnowledge[i] || {};
  const charCode = (k.character_code || ctx.characters_involved[0] || 'CHAR_001').toString().toUpperCase().trim();
  const knowCode = (k.knowledge_key || `KNOW_EP${ctx.episode_no}_${i + 1}`).toString().toUpperCase().trim();
  const knowVal = k.knowledge_value !== undefined ? k.knowledge_value : k.knowledge_fact;
  if (!knowVal) continue;

  safeKnowledgeToUpsert.push({
    project_id: ctx.project_id, character_code: charCode, knowledge_key: knowCode, knowledge_value: String(knowVal),
    learned_at_ep: Number(k.learned_at_ep ?? ctx.episode_no), secret: Boolean(k.secret === true), knows: true
  });
}

const hasCriticalViolation = combinedViolations.some(v => v.type === 'CRITICAL_CANON_VIOLATION' || v.type === 'KNOWLEDGE_GRAPH_VIOLATION');
const isValid = Boolean((parsed?.isValid !== undefined ? Boolean(parsed.isValid) : true) && !hasCriticalViolation);
const shouldMutateDb = Boolean(ctx.operation_mode === 'UPDATE_CANON' && isValid === true && (safeFactsToUpsert.length > 0 || safeKnowledgeToUpsert.length > 0));

return { json: { ...ctx, isValid, violations: combinedViolations, new_facts_to_add: safeFactsToUpsert, new_knowledge_to_add: safeKnowledgeToUpsert, should_mutate_db: shouldMutateDb } };

const state = $('Canon Verdict & Locked Fact Protection Engine').item.json;
const violationsText = state.violations.length > 0 ? state.violations.map((v, i) => `${i + 1}. **[${v.type}]** ${v.description}`).join('\n') : '• Koi Canon Contradiction ya Knowledge Graph Violation nahi mila.';

const summaryMsg = [
  `${state.isValid ? '✅' : '🛑'} **WF-09: Canon Engine & Knowledge Graph Verdict (${state.operation_mode})**`,
  `📁 **Project:** ${state.project_name} | **Episode:** ${state.episode_no} | **Valid:** \`${state.isValid}\``,
  ``, `🔍 **Rule 14/15 & Section 42 Validation Findings (${state.violations.length}):**`, violationsText,
  state.should_mutate_db ? `\n💾 **Database Mutations Committed:**\n• Canon Facts Upserted: ${state.new_facts_to_add.length}\n• Character Knowledge Entries Upserted: ${state.new_knowledge_to_add.length}` : `\n🔒 **Read-Only / Blocked Mode:** Database me koi canon mutation commit nahi kiya gaya.`
].join('\n');

return {
  json: {
    project_id: state.project_id, project_name: state.project_name, episode_no: state.episode_no, episode_number: state.episode_no,
    season_no: state.season_no, season_number: state.season_no, mode: state.mode || 'SAVE', sessionId: state.sessionId,
    intent: state.intent, downstream_command: state.downstream_command || state.intent,
    target_workflow_id: state.target_workflow_id || $env.WF_02_STORY_ID || null, preflight_workflow_ids: state.preflight_workflow_ids || {},
    extracted_params: state.extracted_params || { episode_number: state.episode_no },
    user_prompt: state.user_prompt || state.userPrompt || state.rawText, userPrompt: state.userPrompt || state.user_prompt || state.rawText, rawText: state.rawText || state.user_prompt,
    ok: state.isValid, workflow_name: 'WF-09', execution_id: $execution.id, operation_mode: state.operation_mode,
    isValid: state.isValid, violations: state.violations, new_facts_to_add: state.new_facts_to_add, new_knowledge_to_add: state.new_knowledge_to_add,
    output: summaryMsg, text: summaryMsg
  }
};

